import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as i,af as l}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"RAG","description":"回答必须基于我们自己的文档时，先检索再生成。不要一上来微调。机制见 Learn LLM 第 11–12 章。","frontmatter":{"title":"RAG","description":"回答必须基于我们自己的文档时，先检索再生成。不要一上来微调。机制见 Learn LLM 第 11–12 章。","domain":"tech","tags":["rag"],"llm":[11,12],"prev":false,"next":{"text":"构建语义搜索","link":"/zh/tech/ai-application/building-semantic-search"}},"headers":[],"relativePath":"zh/tech/patterns/RAG.md","filePath":"zh/tech/patterns/RAG.md","lastUpdated":1788250975000}'),r={name:"zh/tech/patterns/RAG.md"};function n(d,t,h,s,o,c){return i(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="rag" tabindex="-1">RAG <a class="header-anchor" href="#rag" aria-label="Permalink to &quot;RAG&quot;">​</a></h1><p><strong>结论</strong>：模型背不住你们的文档、工单和代码。先 <strong>检索出几段带出处的原文</strong>，再让它基于这些段落回答。答不上就拒答。</p><blockquote><p>切块、召回、ACL、引用正确率见 Learn LLM <a href="https://llm.zenheart.site/chapters/11-rag" target="_blank" rel="noreferrer">第 11–12 章</a>。本页只写前端何时上、怎么验收。</p></blockquote><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文档 → 切块 + embedding → 存（原文+来源+权限）</span></span>
<span class="line"><span>用户问题 → embedding → 取 top-k → 拼进提示 → 生成（必须引用）</span></span></code></pre></div><table tabindex="0"><thead><tr><th></th><th>RAG</th><th>把全文塞进窗口</th><th>微调</th></tr></thead><tbody><tr><td>知识会变</td><td>重建索引</td><td>每次重贴</td><td>重训</td></tr><tr><td>成本</td><td>检索 + 少量 token</td><td>窗口费很快爆炸</td><td>高一个数量级</td></tr><tr><td>默认</td><td><strong>先走这条</strong></td><td>只适合单份短文档</td><td>默认不要</td></tr></tbody></table><p>Embedding 概念见 <a href="/zh/tech/fundamentals/embeddings.html">Embeddings</a>。</p><h2 id="这一栏怎么读" tabindex="-1">这一栏怎么读 <a class="header-anchor" href="#这一栏怎么读" aria-label="Permalink to &quot;这一栏怎么读&quot;">​</a></h2><ol><li>读完本页，确认你的问题真的是「必须引用我们的资料」。</li><li>跟一篇可跑的：<a href="/zh/tech/ai-application/building-semantic-search.html">构建语义搜索</a>。</li><li>权限、拒答、评测不够再回 Learn LLM 第 11–12 章，不要在应用站再写一遍原理。</li></ol><h2 id="工程验收-少了就不算做成" tabindex="-1">工程验收（少了就不算做成） <a class="header-anchor" href="#工程验收-少了就不算做成" aria-label="Permalink to &quot;工程验收（少了就不算做成）&quot;">​</a></h2><ol><li>每条回答带 <strong>来源路径或标题</strong>。编不出来就说「文档里没有」。</li><li>索引和查询 <strong>同一 embedding 模型</strong>。</li><li>块不要太大。按标题 / 段落切，不按「一篇文章一块」。</li><li>有权限的文档不能被没权限的人检索到。元数据里带 ACL，过滤发生在召回时，不是生成后再藏。</li><li>用 20 条真实问题当 fixture：该命中的命中，该拒答的拒答。不要只看「感觉通顺」。</li></ol><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li>检索到就当事实。相似度高只表示「像」。</li><li>报错码、函数名走向量搜。先关键词 / grep。</li><li>用微调代替更新文档。知识变了重建索引即可。</li><li>把整仓当一块 embedding。助手场景用 <a href="/zh/tech/fundamentals/context-engineering.html">上下文工程</a>，产品问答才上 RAG。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>动手：<a href="/zh/tech/ai-application/building-semantic-search.html">构建语义搜索</a></li><li>接到聊天 UI：<a href="/zh/integration/apis/streaming.html">流式</a></li><li>默认别微调：<a href="/zh/tech/training/SFT.html">SFT</a></li></ul>`,15)])])}const f=a(r,[["render",n]]);export{u as __pageData,f as default};
